export function createResilientFetch({ fetch, sleep, random = Math.random, maxAttempts = 4, baseDelayMs = 200, maxDelayMs = 5000 }) {
  return async function rfetch(url, options = {}) {
    const retryableStatuses = new Set([408, 429, 500, 502, 503, 504]);
    const safeMethods = new Set(['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE']);
    const idempotentMethods = new Set(['POST', 'PATCH']);

    let attempt = 0;
    let lastError = null;
    let lastResponse = null;

    const method = (options.method || 'GET').toUpperCase();
    const headers = options.headers instanceof Headers ? options.headers : new Headers(options.headers);

    const canRetryMethod = safeMethods.has(method) || (idempotentMethods.has(method) && headers.has('Idempotency-Key'));

    while (attempt < maxAttempts) {
      attempt++;

      if (options.signal && options.signal.aborted) {
        const abortError = new Error('Aborted');
        abortError.name = 'AbortError';
        throw abortError;
      }

      try {
        const response = await fetch(url, options);
        if (response.ok) {
          return response;
        }

        const status = response.status;
        if (!retryableStatuses.has(status)) {
          return response;
        }

        const retryAfter = response.headers.get('Retry-After');
        if (retryAfter && /^\d+$/.test(retryAfter)) {
          const retryAfterMs = parseInt(retryAfter, 10) * 1000;
          if (retryAfterMs > maxDelayMs) {
            return response;
          }
          await sleep(retryAfterMs, options.signal);
        } else {
          const delay = Math.floor(random() * Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1)));
          await sleep(delay, options.signal);
        }

        lastResponse = response;
      } catch (error) {
        if (error.name === 'AbortError') {
          throw error;
        }
        if (!canRetryMethod) {
          throw error;
        }
        lastError = error;
        const delay = Math.floor(random() * Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1)));
        await sleep(delay, options.signal);
      }
    }

    if (lastResponse) {
      return lastResponse;
    }
    throw lastError;
  };
}
